DECLARE @TOTAL_GERAL INT = 31184
DECLARE @TOTAL_PROCESSADO INT
SELECT @TOTAL_PROCESSADO = COUNT(*) 
FROM @TAB_PRD A
INNER JOIN PRODUTOS P (NOLOCK) 
	ON P.PRODUTO = A.PRODUTO
		AND P.GRIFFE = A.GRIFFE
		AND P.LINHA = A.LINHA
		AND P.GRUPO_PRODUTO = A.GRUPO_PRODUTO
		AND P.SUBGRUPO_PRODUTO = A.SUBGRUPO_PRODUTO

SELECT @TOTAL_GERAL AS TOTAL_GERAL, @TOTAL_PROCESSADO AS TOTAL_PROCESSADO, (@TOTAL_GERAL - @TOTAL_PROCESSADO) AS FALTA
